"""Separate scheduled sampling from recorded-state activity and physical energy."""
import csv,json
import numpy as np
from .state_activity_math import OUT,sha

def main():
    p=json.loads((OUT/'protocol.json').read_text());m=json.loads((OUT/'manifest.json').read_text());a=json.loads((OUT/'evidence_audit.json').read_text());data=json.loads((OUT/'ledger.json').read_text());assert a['passed'] and a['producer_manifest_sha256']==sha(OUT/'manifest.json')
    for source,h in p['source_sha256'].items():assert sha(source)==h
    for name,rows in [('layer_activity.csv',data['rows']),('aggregate_activity.csv',data['totals'])]:
        with (OUT/name).open('w',newline='') as f:w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
    lines=['# Matched sampling is not matched recorded-state activity','','This follows the closed neural comparison, using exactly its frozen24-matrix group16 controls and42,467,328 normalized weights. One-node probabilities use the eight-bit field grid[-4,4]; four-node positional bits use fields+/-4. No new model task scores, method selection, quality threshold or physical-device measurements occur. The ledger below is an analytic expectation for all learned controls, independently checked. A separate native witness validates the discrete state-count laws; it does not measure every previous neural trajectory.','','## What is counted','','For IID Bernoulli probability p, a call initialized False with T recorded updates has expected observed changes p+2(T-1)p(1-p). If the initial state is already an independent stationary draw, T subsequent transitions have expectation2Tp(1-p). Resetting a mostly-one positional bit incurs an initial change that retained operation avoids. Neither number counts unobserved physical changes between sample instants. These are discrete recorded-state proxies, not physical switching-energy measurements.','','Every full32-context forward uses four separate weight-bank calls in the neural study. The table normalizes to one bank and one converted weight, including all four positional devices when K=4. At equal U updates/weight, single T=U and positional T=U/4.','','| Updates/weight | Single reset changes | Four-node reset changes | Single retained changes | Four-node retained changes | Retained single/four ratio |','|---:|---:|---:|---:|---:|---:|']
    ratios=[]
    for budget in [4,16,64,256]:
        one=next(r for r in data['totals'] if r['updates_per_weight']==budget and r['K']==1);multi=next(r for r in data['totals'] if r['updates_per_weight']==budget and r['K']==4);ratio=one['retained_changes_per_weight_per_bank']/multi['retained_changes_per_weight_per_bank'];ratios.append(ratio);lines.append(f'| {budget} | {one["reset_changes_per_weight_per_bank"]:.6f} | {multi["reset_changes_per_weight_per_bank"]:.6f} | {one["retained_changes_per_weight_per_bank"]:.6f} | {multi["retained_changes_per_weight_per_bank"]:.6f} | {ratio:.3f} |')
    lines+=['','Interior probabilities change more often than near-deterministic fields at a fixed number of IID observations. This does not establish physical energy ordering: field-dependent holding power, control circuits, bias-programming/reuse, readout, arithmetic, sampling correlation/rate and hidden physical events remain unmeasured. Equal scheduled updates alone cannot establish equal energy.','','## Native witness and independent audit','',f'The official pinned THRML CPU sampler exercises all256 admissible field codes, T=1/4/16/64/256, five sampling seeds x200 trials each. Each call emits T+1 states. The firstT records supply the False-reset count; the T adjacent record gaps supply retained counts. These two windows overlap and are not independent replications. AllT+1 initialization/observation updates are charged: **{m["native_node_updates"]:,}** production and **{a["independent_native_updates"]:,}** independent replay. A separate public raw-state program reproduces all **{a["public_counter_and_state_elements_exact"]:,}** state/counter entries exactly. Direction sums and telescoping state identities pass. Independent moment recursions check the analytic means/variances; all2560 nominal IID mean conditions pass the frozen familyalpha.01 Bernstein bounds. Small-sequence exhaustive enumeration additionally tests both initialization laws.','','All192 per-layer/budget/method rows and8 full-control aggregate rows are independently recomputed by expanding actual bit planes, rather than the producer\'s popcount simplification. Complete raw witness counters, final/initial states, fields, seeds and source hashes are retained. Full-model expected activity is not upgraded into a measured full-model flip count. The existing node-update, model-quality and earlier failure records remain unchanged.','','## Conditional cost accounting','','A non-overlapping hypothetical cost model can include U*e_eval + R*e_read + F_recorded*e_change + E_hold + E_program + E_accumulate + E_calibrate. Its coefficients need actual measurements, and F_recorded is only a proxy for physical event activity. If a measured per-update cost already includes switching, adding another switching charge double-counts it. Retained static weights may amortize programming; a layer-reused bank changes fields and initialization and needs its own schedule. Idle state activity is outside the active-update ledger.','','No joule, nanosecond or device-area number is inferred here. Lower recorded activity does not make this internal positional word an established Extropic architecture. The one-p-bit probability representation remains supported; a hardware systems advantage and the full Boolean-classifier comparison remain open. The long-horizon goal stays active.']
    report=OUT.parent/'STATE_ACTIVITY_REPORT.md';report.write_text('\n'.join(lines)+'\n')
    import matplotlib;matplotlib.use('Agg');import matplotlib.pyplot as plt
    fig,axes=plt.subplots(1,2,figsize=(10,4),layout='constrained')
    for ax,mode in zip(axes,['reset','retained']):
        for k,label in [(1,'One p-bit'),(4,'Four positional p-bits')]:
            rr=[r for r in data['totals'] if r['K']==k];ax.loglog([r['updates_per_weight'] for r in rr],[r[mode+'_changes_per_weight_per_bank'] for r in rr],'o-',label=label)
        ax.set(xlabel='Equal scheduled node updates per weight',ylabel='Expected recorded changes per weight/bank',title='False initialization' if mode=='reset' else 'Stationary retained initialization');ax.legend()
    fig.savefig(OUT.parent/'state_activity.png',dpi=180);plt.close(fig);print(report)
if __name__=='__main__':main()
